// ---- plumbing --------------------------------------------------------------------------------------------------------

/// Run `f` for every item on up to `jobs` threads; results keep the order of `items`.
pub fn par_map<T: Sync, R: Send>(items: &[T], jobs: usize, f: impl Fn(&T) -> R + Sync) -> Vec<R> {
    let next = AtomicUsize::new(0);
    let out: Mutex<Vec<Option<R>>> = Mutex::new(items.iter().map(|_| None).collect());
    std::thread::scope(|s| {
        for _ in 0..jobs.clamp(1, items.len().max(1)) {
            s.spawn(|| {
                loop {
                    let i = next.fetch_add(1, Ordering::SeqCst);
                    let Some(item) = items.get(i) else { break };
                    let r = f(item);
                    out.lock().unwrap()[i] = Some(r);
                }
            });
        }
    });
    out.into_inner()
        .unwrap()
        .into_iter()
        .map(|r| r.expect("every item was processed"))
        .collect()
}

pub(crate) fn last_lines(s: &str, n: usize) -> String {
    let v: Vec<&str> = s.lines().filter(|l| !l.trim().is_empty()).collect();
    v[v.len().saturating_sub(n)..].join(" | ")
}

fn read_token(file: Option<&PathBuf>, stdin: bool) -> Result<Option<Secret>> {
    let raw = match (file, stdin) {
        (Some(_), true) => bail!("use --token-file or --token-stdin, not both"),
        (Some(p), false) => {
            let p = expand_home(p);
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                let mode = std::fs::metadata(&p)
                    .map_err(|e| anyhow::anyhow!("token file {}: {e}", p.display()))?
                    .permissions()
                    .mode();
                if mode & 0o077 != 0 {
                    bail!(
                        "token file {} is readable by others (mode {:o}): `chmod 600 {}`",
                        p.display(),
                        mode & 0o777,
                        p.display()
                    );
                }
            }
            std::fs::read_to_string(&p)
                .map_err(|e| anyhow::anyhow!("token file {}: {e}", p.display()))?
        }
        (None, true) => {
            let mut s = String::new();
            std::io::Read::read_to_string(&mut std::io::stdin(), &mut s)?;
            s
        }
        (None, false) => return Ok(None),
    };
    let t = raw.trim();
    if t.len() < 8 || t.len() > 512 || !t.bytes().all(|c| c.is_ascii_graphic()) {
        bail!("the join token is empty or not a single printable word");
    }
    Ok(Some(Secret::new(t.as_bytes().to_vec())))
}

/// Which Macs a command acts on, with the inventory's per-host settings, and the inventory itself.
pub(crate) fn resolve(w: &Which, conn: &Conn) -> Result<(Vec<Target>, Option<Inventory>)> {
    let inv = w.inventory.as_deref().map(Inventory::load).transpose()?;
    let mut targets = vec![];
    match (&inv, w.hosts.is_empty()) {
        (None, true) => bail!("name the Macs (`user@host`) or pass --inventory FILE"),
        (None, false) if w.all => bail!("--all needs --inventory"),
        (Some(i), true) => targets = i.targets()?,
        (_, false) => {
            let known = inv
                .as_ref()
                .map(|i| i.targets())
                .transpose()?
                .unwrap_or_default();
            for h in &w.hosts {
                match known.iter().find(|t| &t.name == h || &t.host == h) {
                    Some(t) => targets.push(t.clone()),
                    None => targets.push(Target::parse(h)?),
                }
            }
        }
    }
    for t in &mut targets {
        if t.identity.is_none() {
            t.identity = conn.identity.clone();
        }
    }
    let mut seen = std::collections::BTreeSet::new();
    for t in &targets {
        if !seen.insert(t.host.clone() + &t.port.map(|p| p.to_string()).unwrap_or_default()) {
            bail!("{} is listed twice", t.label());
        }
    }
    Ok((targets, inv))
}

pub(crate) fn transport(conn: &Conn, inv: Option<&Inventory>) -> Box<dyn Transport> {
    let opts = SshOpts {
        identity: conn.identity.clone(),
        known_hosts: conn
            .known_hosts
            .clone()
            .or_else(|| inv.and_then(|i| i.known_hosts.clone()))
            .map(|p| expand_home(&p)),
        accept_new: conn.accept_new_hostkey,
        connect_timeout_secs: conn.connect_timeout,
    };
    if conn.dry_run {
        Box::new(DryTransport::new(opts))
    } else {
        let mut t = SshTransport::new(opts);
        t.step_timeout = (conn.step_timeout > 0).then(|| std::time::Duration::from_secs(conn.step_timeout));
        Box::new(t)
    }
}

pub fn build_settings(
    f: &UpFlags,
    inv: Option<&Inventory>,
    targets: &mut [Target],
    name: Option<&str>,
) -> Result<Settings> {
    let version = f
        .release
        .clone()
        .or_else(|| inv.and_then(|i| i.version.clone()))
        .unwrap_or_else(|| env!("CARGO_PKG_VERSION").to_owned());
    if f.via == Via::Release && !valid_version(&version) {
        bail!(
            "--release {version:?} must be a release number such as 0.4.21 (`latest` is refused: pin what the fleet runs)"
        );
    }
    let sha256 = f
        .sha256
        .clone()
        .or_else(|| inv.and_then(|i| i.sha256.clone()));
    if let Some(s) = &sha256
        && !valid_sha256(s)
    {
        bail!("--sha256 must be 64 hex digits");
    }
    let release_base = f
        .release_base
        .clone()
        .or_else(|| inv.and_then(|i| i.release_base.clone()))
        .unwrap_or_else(|| DEFAULT_RELEASE_BASE.to_owned());
    let central = f
        .central
        .clone()
        .or_else(|| inv.and_then(|i| i.central.clone()));
    let advertise_url = f
        .advertise_url
        .clone()
        .or_else(|| inv.and_then(|i| i.advertise_url.clone()));
    for (n, u) in [
        ("--release-base", Some(&release_base)),
        ("--central", central.as_ref()),
    ] {
        if let Some(u) = u
            && !valid_url(u)
        {
            bail!("{n} {u:?} must be an http(s):// URL without shell characters");
        }
    }
    if let Some(u) = &advertise_url
        && !valid_url(&u.replace("{host}", "h").replace("{name}", "n"))
    {
        bail!("--advertise-url {u:?} must be an http(s):// URL without shell characters");
    }
    for l in &f.labels {
        if !valid_label(l) {
            bail!("--label {l:?} must be key=value without spaces or shell characters");
        }
    }
    let token_file = f
        .token_file
        .clone()
        .or_else(|| inv.and_then(|i| i.token_file.clone()));
    let token = if central.is_some() || f.token_stdin || f.token_file.is_some() {
        read_token(token_file.as_ref(), f.token_stdin)?
    } else {
        None
    };
    if token.is_some() && central.is_none() {
        bail!("a join token needs --central (or `central:` in the inventory)");
    }
    if let Some(n) = name {
        if targets.len() != 1 {
            bail!("--name is for a single Mac");
        }
        if !valid_node_name(n) {
            bail!("--name must be lowercase letters, digits, dashes and dots");
        }
        targets[0].name = n.to_owned();
    }
    let mut k = inv.map(|i| i.k3s_spec()).unwrap_or_default();
    k.cpus = f.k3s_cpus.unwrap_or(k.cpus);
    k.memory_mib = f.k3s_memory_mib.unwrap_or(k.memory_mib);
    k.disk_gib = f.k3s_disk_gib.unwrap_or(k.disk_gib);
    k.wait_secs = f.k3s_wait.unwrap_or(k.wait_secs);
    for t in targets.iter_mut() {
        t.k3s |= f.k3s;
        if !valid_node_name(&t.name) {
            bail!(
                "{}: the node name {:?} is not valid; pass --name",
                t.label(),
                t.name
            );
        }
    }
    Ok(Settings {
        install: InstallSpec {
            version,
            sha256,
            release_base,
            via: f.via,
        },
        central,
        advertise_url,
        token,
        k3s: k,
        labels: f.labels.clone(),
        all_k3s: f.k3s,
    })
}

// ---- per-host work ---------------------------------------------------------------------------------------------------

pub(crate) fn fail(mut r: HostResult, msg: impl Into<String>) -> HostResult {
    r.ok = false;
    r.error = Some(msg.into());
    r
}

/// The probe: `Ok(facts)`, or the host result to return when the Mac cannot be reached or the probe broke.
fn probe(
    t: &dyn Transport,
    target: &Target,
    r: &HostResult,
) -> std::result::Result<Facts, HostResult> {
    match t.run(target, &remote(&probe_script()), None) {
        Err(e) => Err(fail(r.clone(), format!("{e:#}"))),
        Ok(o) if o.ssh_failed() => Err(fail(r.clone(), explain_ssh_failure(target, &o.stderr))),
        Ok(o) if !o.ok() => Err(fail(
            r.clone(),
            format!("the probe failed: {}", last_lines(&o.stderr, 3)),
        )),
        Ok(o) => Ok(parse_facts(&o.stdout)),
    }
}

pub(crate) fn blank(target: &Target) -> HostResult {
    HostResult {
        host: target.label(),
        name: target.name.clone(),
        ..Default::default()
    }
}

fn run_steps(
    t: &dyn Transport,
    target: &Target,
    steps: &[Step],
    token: Option<&Secret>,
    mut r: HostResult,
) -> HostResult {
    for s in steps {
        let stdin = (s.stdin == StepIn::Token).then_some(token).flatten();
        match t.run(target, &remote(&s.script), stdin) {
            Err(e) => {
                r.steps.push(StepResult {
                    name: s.name.into(),
                    ok: false,
                    output: scrub(&format!("{e:#}"), token),
                });
                return fail(r, format!("{}: {e:#}", s.name));
            }
            Ok(o) if o.ssh_failed() => {
                r.steps.push(StepResult {
                    name: s.name.into(),
                    ok: false,
                    output: scrub(&o.stderr, token),
                });
                return fail(r, explain_ssh_failure(target, &o.stderr));
            }
            Ok(o) => {
                let ok = o.ok();
                let text = if ok {
                    last_lines(&o.stdout, 1)
                } else {
                    last_lines(&format!("{}\n{}", o.stdout, o.stderr), 3)
                };
                r.steps.push(StepResult {
                    name: s.name.into(),
                    ok,
                    output: scrub(&text, token),
                });
                if !ok {
                    return fail(
                        r,
                        format!("step `{}` failed: {}", s.name, scrub(&text, token)),
                    );
                }
            }
        }
    }
    r.ok = true;
    r
}

pub fn up_host(t: &dyn Transport, target: &Target, s: &Settings) -> HostResult {
    let r = blank(target);
    let facts = match probe(t, target, &r) {
        Ok(f) => f,
        Err(r) => return r,
    };
    let want = Want {
        enroll: s.central.is_some(),
        k3s: target.k3s,
    };
    let findings = check(&facts, want);
    let mut r = r;
    r.findings = findings
        .iter()
        .filter(|f| f.level != Level::Ok)
        .cloned()
        .collect();
    if has_errors(&findings) {
        let msgs: Vec<String> = findings
            .iter()
            .filter(|f| f.level == Level::Error)
            .map(|f| format!("{} (fix: {})", f.msg, f.fix))
            .collect();
        return fail(r, format!("preflight failed: {}", msgs.join("; ")));
    }
    if s.install.via == Via::Release
        && let Some(cur) = &facts.fluxctl_version
        && cur != &s.install.version
    {
        return fail(
            r,
            format!(
                "FluxVM {cur} is installed and {} was asked for: `fluxctl mac-fleet upgrade --release {}` moves it",
                s.install.version, s.install.version
            ),
        );
    }
    let enroll = s.central.as_ref().map(|c| EnrollSpec {
        name: target.name.clone(),
        central: c.clone(),
        advertise_url: s.advertise_url.as_ref().map(|u| {
            u.replace("{host}", &target.host)
                .replace("{name}", &target.name)
        }),
        labels: s.labels.iter().chain(&target.labels).cloned().collect(),
    });
    if enroll.is_some() && facts.known && !facts.enrolled && s.token.is_none() {
        return fail(
            r,
            "not enrolled and no join token: create one (docs/fleet-enroll.md) and pass --token-file FILE (or --token-stdin)",
        );
    }
    let spec = UpSpec {
        install: s.install.clone(),
        enroll,
        have_token: s.token.is_some(),
        k3s: target.k3s.then(|| s.k3s.clone()),
    };
    run_steps(t, target, &plan_up(&facts, &spec), s.token.as_ref(), r)
}

pub fn upgrade_host(
    t: &dyn Transport,
    target: &Target,
    install: &InstallSpec,
    force: bool,
) -> HostResult {
    let r = blank(target);
    let facts = match probe(t, target, &r) {
        Ok(f) => f,
        Err(r) => return r,
    };
    if facts.known {
        let findings = check(&facts, Want::default());
        if has_errors(&findings) {
            let msgs: Vec<String> = findings
                .iter()
                .filter(|f| f.level == Level::Error)
                .map(|f| format!("{} (fix: {})", f.msg, f.fix))
                .collect();
            return fail(r, format!("preflight failed: {}", msgs.join("; ")));
        }
        if facts.fluxctl_version.is_none() {
            return fail(
                r,
                "FluxVM is not installed here: use `fluxctl mac-fleet up`",
            );
        }
        if facts.running_vms() > 0 && !force {
            return fail(
                r,
                format!(
                    "{} VM(s) are running and the daemon restarts: stop them, or pass --force",
                    facts.running_vms()
                ),
            );
        }
    }
    run_steps(t, target, &plan_upgrade(install), None, r)
}

pub fn remove_host(t: &dyn Transport, target: &Target, k3s: bool, purge: bool) -> HostResult {
    let steps = [Step {
        name: "remove",
        script: remove_script(k3s, purge),
        stdin: StepIn::None,
    }];
    run_steps(t, target, &steps, None, blank(target))
}

pub fn doctor_host(t: &dyn Transport, target: &Target, want: Want) -> HostResult {
    let r = blank(target);
    let facts = match probe(t, target, &r) {
        Ok(f) => f,
        Err(r) => return r,
    };
    let mut r = r;
    r.findings = check(&facts, want);
    if facts.known {
        r.findings.extend(installed_findings(&facts));
    }
    r.ok = !has_errors(&r.findings);
    if !r.ok {
        r.error = Some("preflight found problems".into());
    }
    r
}

fn installed_findings(f: &Facts) -> Vec<Finding> {
    let mk = |level, id, msg: &str, fix: &str| Finding {
        level,
        id,
        msg: msg.into(),
        fix: fix.into(),
    };
    match &f.fluxctl_version {
        None => vec![mk(
            Level::Warn,
            "installed",
            "FluxVM is not installed",
            "fluxctl mac-fleet up HOST",
        )],
        Some(v) => {
            let mut out = vec![Finding {
                level: Level::Ok,
                id: "installed",
                msg: format!("FluxVM {v}"),
                fix: String::new(),
            }];
            if !f.daemon_loaded {
                out.push(mk(
                    Level::Warn,
                    "daemon",
                    "the daemon LaunchAgent is not loaded",
                    "fluxctl mac-fleet up HOST (or `fluxctl service install` on the Mac)",
                ));
            } else if !f.daemon_healthy {
                out.push(mk(Level::Error, "daemon", "the daemon is loaded but does not answer /healthz", "tail ~/Library/Logs/fluxvm.log on the Mac; `launchctl kickstart -k gui/$(id -u)/dev.zyvor.fluxvm`"));
            }
            out
        }
    }
}

pub fn status_host(t: &dyn Transport, target: &Target) -> StatusRow {
    let dash = || "-".to_owned();
    let mut row = StatusRow {
        host: target.label(),
        state: "unreachable".into(),
        version: dash(),
        daemon: dash(),
        vms: dash(),
        macos_slots: dash(),
        k3s: dash(),
        node: dash(),
        error: None,
    };
    let facts = match probe(t, target, &blank(target)) {
        Ok(f) => f,
        Err(r) => {
            row.error = r.error;
            return row;
        }
    };
    row.state = "ok".into();
    if !facts.known {
        return row;
    }
    row.version = facts
        .fluxctl_version
        .clone()
        .unwrap_or_else(|| "not installed".into());
    row.daemon = match (facts.daemon_healthy, facts.daemon_loaded) {
        (true, _) => "up",
        (false, true) => "down",
        (false, false) => "off",
    }
    .into();
    if let Some((total, macos)) = facts.vm_counts() {
        row.vms = total.to_string();
        row.macos_slots = format!("{macos}/{MACOS_SLOTS}");
    }
    row.k3s = facts.k3s_state();
    row.node = match (facts.enrolled, facts.agent_loaded) {
        (true, true) => "enrolled",
        (false, true) => "joining",
        (true, false) => "agent off",
        (false, false) => "-",
    }
    .into();
    row
}

pub fn exec_host(t: &dyn Transport, target: &Target, cmd: &[String]) -> (HostResult, String) {
    let r = blank(target);
    match t.run(target, &remote(&exec_script(cmd)), None) {
        Err(e) => (fail(r, format!("{e:#}")), String::new()),
        Ok(o) if o.ssh_failed() => (
            fail(r, explain_ssh_failure(target, &o.stderr)),
            String::new(),
        ),
        Ok(o) => {
            let text = if o.stderr.is_empty() {
                o.stdout.clone()
            } else {
                format!("{}{}", o.stdout, o.stderr)
            };
            let mut r = r;
            r.ok = o.ok();
            if !o.ok() {
                r.error = Some(format!("exit status {}", o.code));
            }
            (r, text)
        }
    }
}

// ---- output ----------------------------------------------------------------------------------------------------------

pub fn render_table(headers: &[&str], rows: &[Vec<String>]) -> String {
    let mut w: Vec<usize> = headers.iter().map(|h| h.len()).collect();
    for r in rows {
        for (i, c) in r.iter().enumerate() {
            w[i] = w[i].max(c.chars().count());
        }
    }
    let line = |cells: Vec<&str>| {
        let mut s = String::new();
        for (i, c) in cells.iter().enumerate() {
            if i + 1 == cells.len() {
                s.push_str(c);
            } else {
                s.push_str(&format!("{:<width$}  ", c, width = w[i]));
            }
        }
        s.trim_end().to_owned() + "\n"
    };
    let mut out = line(headers.to_vec());
    for r in rows {
        out.push_str(&line(r.iter().map(String::as_str).collect()));
    }
    out
}

pub fn render_status(rows: &[StatusRow]) -> String {
    let mut out = render_table(
        &[
            "HOST", "STATE", "VERSION", "DAEMON", "VMS", "MACOS", "K3S", "NODE",
        ],
        &rows
            .iter()
            .map(|r| {
                vec![
                    r.host.clone(),
                    r.state.clone(),
                    r.version.clone(),
                    r.daemon.clone(),
                    r.vms.clone(),
                    r.macos_slots.clone(),
                    r.k3s.clone(),
                    r.node.clone(),
                ]
            })
            .collect::<Vec<_>>(),
    );
    for r in rows {
        if let Some(e) = &r.error {
            out.push_str(&format!("\n{}: {e}", r.host));
        }
    }
    out
}

pub fn render_results(verb: &str, rs: &[HostResult]) -> String {
    let rows: Vec<Vec<String>> = rs
        .iter()
        .map(|r| {
            let detail = match (&r.error, r.steps.last()) {
                (Some(e), _) => e.clone(),
                (None, Some(s)) => s.output.clone(),
                _ => String::new(),
            };
            vec![
                r.host.clone(),
                if r.ok { "ok".into() } else { "FAILED".into() },
                detail,
            ]
        })
        .collect();
    let mut out = render_table(&["HOST", verb, "DETAIL"], &rows);
    for r in rs {
        let warns: Vec<_> = r
            .findings
            .iter()
            .filter(|f| f.level == Level::Warn)
            .collect();
        for w in warns {
            out.push_str(&format!("\nwarning {}: {} -> {}", r.host, w.msg, w.fix));
        }
    }
    out
}

pub fn render_doctor(rs: &[HostResult]) -> String {
    let mut out = String::new();
    for r in rs {
        out.push_str(&format!("{}\n", r.host));
        if r.findings.is_empty() {
            out.push_str(&format!(
                "  FAIL  {}\n",
                r.error.clone().unwrap_or_else(|| "no findings".into())
            ));
        }
        for f in &r.findings {
            let tag = match f.level {
                Level::Ok => "ok   ",
                Level::Warn => "warn ",
                Level::Error => "FAIL ",
            };
            out.push_str(&format!("  {tag} {}\n", f.msg));
            if !f.fix.is_empty() {
                out.push_str(&format!("        fix: {}\n", f.fix));
            }
        }
    }
    out
}

pub(crate) fn finish(rs: &[HostResult], what: &str) -> Result<()> {
    let bad = rs.iter().filter(|r| !r.ok).count();
    if bad > 0 {
        bail!(
            "{what} failed on {bad} of {} Macs (the others are done; fix and re-run, it is idempotent)",
            rs.len()
        );
    }
    Ok(())
}

fn print_dry(tr: &dyn Transport, targets: &[Target]) {
    let _ = targets;
    eprintln!("# dry run: nothing was sent to any Mac. Each command below is what would run.");
    if let Some(d) = tr.as_dry() {
        for l in d.lines.lock().unwrap().iter() {
            println!("{l}");
        }
    }
}

pub(crate) fn jobs(conn: &Conn) -> usize {
    if conn.dry_run { 1 } else { conn.jobs }
}

// ---- entry -----------------------------------------------------------------------------------------------------------

pub fn run(cmd: MacFleetCommand) -> Result<()> {
    match cmd {
        MacFleetCommand::Up(a) => {
            let (mut targets, inv) = resolve(&a.which, &a.conn)?;
            let s = build_settings(&a.flags, inv.as_ref(), &mut targets, a.name.as_deref())?;
            do_up(&a.conn, inv.as_ref(), &targets, &s)
        }
        MacFleetCommand::Apply(a) => {
            let which = Which {
                hosts: vec![],
                inventory: Some(a.file.clone()),
                all: true,
            };
            let (mut targets, inv) = resolve(&which, &a.conn)?;
            let s = build_settings(&a.flags, inv.as_ref(), &mut targets, None)?;
            let up = do_up(&a.conn, inv.as_ref(), &targets, &s);
            let inv_key = crate::mac_fleet_inv::resolve_path(&a.file)
                .and_then(|p| Ok(p.canonicalize()?))
                .map(|p| p.display().to_string())?;
            crate::mac_fleet_run::after_apply(
                &a.conn,
                transport(&a.conn, inv.as_ref()).as_ref(),
                &inv_key,
                &targets,
                a.prune,
                &crate::mac_fleet_sched::state_path()?,
            )?;
            up?;
            if !a.conn.dry_run {
                println!();
                do_status(&a.conn, inv.as_ref(), &targets)?;
            }
            Ok(())
        }
        MacFleetCommand::Status(a) => {
            let (targets, inv) = resolve(&a.which, &a.conn)?;
            if a.detail {
                return crate::mac_fleet_status::status_detail_cmd(&a.conn, inv.as_ref(), &targets);
            }
            do_status(&a.conn, inv.as_ref(), &targets)
        }
        MacFleetCommand::Exec(a) => {
            let (targets, inv) = resolve(&a.which, &a.conn)?;
            let tr = transport(&a.conn, inv.as_ref());
            let rs = par_map(&targets, jobs(&a.conn), |t| {
                exec_host(tr.as_ref(), t, &a.cmd)
            });
            if a.conn.dry_run {
                print_dry(tr.as_ref(), &targets);
                return Ok(());
            }
            if a.conn.json {
                let v: Vec<_> = rs.iter().map(|(r, out)| serde_json::json!({"host": r.host, "ok": r.ok, "error": r.error, "output": out})).collect();
                println!("{}", serde_json::to_string_pretty(&v)?);
            } else {
                for (r, out) in &rs {
                    println!("== {} {}", r.host, if r.ok { "" } else { "(failed)" });
                    print!("{out}");
                    if !out.is_empty() && !out.ends_with('\n') {
                        println!();
                    }
                    if let (false, Some(e)) = (r.ok, &r.error) {
                        println!("   {e}");
                    }
                }
            }
            let only: Vec<HostResult> = rs.into_iter().map(|(r, _)| r).collect();
            finish(&only, "exec")
        }
        MacFleetCommand::Upgrade(a) => {
            let (targets, inv) = resolve(&a.which, &a.conn)?;
            let flags = UpFlags {
                release: a.release.clone(),
                sha256: a.sha256.clone(),
                release_base: a.release_base.clone(),
                via: a.via,
                central: None,
                advertise_url: None,
                token_file: None,
                token_stdin: false,
                k3s: false,
                k3s_cpus: None,
                k3s_memory_mib: None,
                k3s_disk_gib: None,
                k3s_wait: None,
                labels: vec![],
            };
            let mut targets = targets;
            let s = build_settings(&flags, inv.as_ref(), &mut targets, None)?;
            let tr = transport(&a.conn, inv.as_ref());
            if a.rolling {
                return crate::mac_fleet_roll::roll_cmd(
                    &a.conn,
                    tr.as_ref(),
                    &targets,
                    &s.install,
                    crate::mac_fleet_roll::RollOpts { drain_timeout: a.drain_timeout, health_timeout: a.health_timeout, poll: 10 },
                );
            }
            let rs = par_map(&targets, jobs(&a.conn), |t| {
                upgrade_host(tr.as_ref(), t, &s.install, a.force)
            });
            report(&a.conn, tr.as_ref(), &targets, &rs, "UPGRADE")?;
            finish(&rs, "upgrade")
        }
        MacFleetCommand::Remove(a) => {
            let (targets, inv) = resolve(&a.which, &a.conn)?;
            if !a.yes && !a.conn.dry_run {
                bail!(
                    "this would remove FluxVM (LaunchAgents and install, not VM data) from {} Mac(s): {}. Re-run with --yes, or --dry-run to see the commands",
                    targets.len(),
                    targets
                        .iter()
                        .map(|t| t.label())
                        .collect::<Vec<_>>()
                        .join(", ")
                );
            }
            let tr = transport(&a.conn, inv.as_ref());
            let rs = par_map(&targets, jobs(&a.conn), |t| {
                remove_host(tr.as_ref(), t, a.k3s, a.purge)
            });
            report(&a.conn, tr.as_ref(), &targets, &rs, "REMOVE")?;
            finish(&rs, "remove")
        }
        MacFleetCommand::Run(a) => crate::mac_fleet_run::run_cmd(a),
        MacFleetCommand::Drain(a) => crate::mac_fleet_run::drain_cmd(a, true),
        MacFleetCommand::Resume(a) => crate::mac_fleet_run::drain_cmd(a, false),
        MacFleetCommand::Templates { command } => crate::mac_fleet_run::templates_cmd(command),
        MacFleetCommand::Doctor(a) => {
            let (targets, inv) = resolve(&a.which, &a.conn)?;
            let tr = transport(&a.conn, inv.as_ref());
            let want = Want {
                enroll: a.enroll,
                k3s: a.k3s,
            };
            let rs = par_map(&targets, jobs(&a.conn), |t| {
                doctor_host(tr.as_ref(), t, want)
            });
            if a.conn.dry_run {
                print_dry(tr.as_ref(), &targets);
                return Ok(());
            }
            if a.conn.json {
                println!("{}", serde_json::to_string_pretty(&rs)?);
            } else {
                print!("{}", render_doctor(&rs));
            }
            finish(&rs, "doctor")
        }
    }
}

fn report(
    conn: &Conn,
    tr: &dyn Transport,
    targets: &[Target],
    rs: &[HostResult],
    verb: &str,
) -> Result<()> {
    if conn.dry_run {
        print_dry(tr, targets);
    } else if conn.json {
        println!("{}", serde_json::to_string_pretty(rs)?);
    } else {
        println!("{}", render_results(verb, rs));
    }
    Ok(())
}

fn do_up(conn: &Conn, inv: Option<&Inventory>, targets: &[Target], s: &Settings) -> Result<()> {
    let tr = transport(conn, inv);
    let rs = par_map(targets, jobs(conn), |t| up_host(tr.as_ref(), t, s));
    report(conn, tr.as_ref(), targets, &rs, "UP")?;
    finish(&rs, "up")
}

fn do_status(conn: &Conn, inv: Option<&Inventory>, targets: &[Target]) -> Result<()> {
    let tr = transport(conn, inv);
    let rows = par_map(targets, jobs(conn), |t| status_host(tr.as_ref(), t));
    if conn.dry_run {
        print_dry(tr.as_ref(), targets);
        return Ok(());
    }
    if conn.json {
        println!("{}", serde_json::to_string_pretty(&rows)?);
    } else {
        println!("{}", render_status(&rows));
    }
    let bad = rows.iter().filter(|r| r.state != "ok").count();
    if bad > 0 {
        bail!("{bad} of {} Macs could not be reached", rows.len());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::mac_fleet_ssh::fake::*;

    fn settings(token: Option<&str>) -> Settings {
        Settings {
            install: InstallSpec {
                version: "0.4.21".into(),
                sha256: None,
                release_base: DEFAULT_RELEASE_BASE.into(),
                via: Via::Release,
            },
            central: Some("https://fleet.example:7790".into()),
            advertise_url: None,
            token: token.map(|t| Secret::new(t.as_bytes().to_vec())),
            k3s: K3sSpec::default(),
            labels: vec![],
            all_k3s: false,
        }
    }

    const FRESH: &str = "os=Darwin\narch=arm64\nmacos=15.1\nuser=admin\nconsole_user=admin\ndisk_free_gib=200\nfilevault=FileVault is Off.\nautologin=admin\nbrew=yes\nfluxctl_version=\nagent_binary=no\ndaemon_loaded=no\nagent_loaded=no\nkube_loaded=no\ndaemon_healthy=no\nenrolled=no\nvms_json=\nkube_json=\n";

    fn is_probe(cmd: &str) -> bool {
        cmd.contains("echo \"os=$(uname -s)\"")
    }

    fn healthy_fake() -> FakeTransport {
        FakeTransport::new(|_, cmd| {
            if is_probe(cmd) {
                ok(FRESH)
            } else {
                ok("done\n")
            }
        })
    }

    #[test]
    fn a_fresh_mac_gets_install_daemon_token_enroll_and_k3s_in_order() {
        let f = healthy_fake();
        let mut t = Target::parse("admin@mini-1.local").unwrap();
        t.k3s = true;
        let r = up_host(&f, &t, &settings(Some("fvjt_abc.SECRETSECRET")));
        assert!(r.ok, "{:?}", r.error);
        let names: Vec<_> = r.steps.iter().map(|s| s.name.as_str()).collect();
        assert_eq!(names, ["install", "daemon", "join-token", "enroll", "k3s"]);
        // the token reached exactly one call, on stdin, and is in no command line
        let calls = f.calls_for("mini-1.local");
        assert_eq!(calls.iter().filter(|c| c.stdin.is_some()).count(), 1);
        assert_eq!(
            calls
                .iter()
                .find(|c| c.stdin.is_some())
                .unwrap()
                .stdin
                .as_deref(),
            Some(&b"fvjt_abc.SECRETSECRET"[..])
        );
        assert!(calls.iter().all(|c| !c.command.contains("SECRETSECRET")));
        assert!(!format!("{r:?}").contains("SECRETSECRET"));
    }

    #[test]
    fn a_rerun_on_a_converged_mac_does_not_resend_the_token() {
        let converged = FRESH
            .replace("fluxctl_version=", "fluxctl_version=0.4.21")
            .replace("agent_binary=no", "agent_binary=yes")
            .replace("enrolled=no", "enrolled=yes")
            .replace("agent_loaded=no", "agent_loaded=yes")
            .replace("daemon_loaded=no", "daemon_loaded=yes")
            .replace("daemon_healthy=no", "daemon_healthy=yes");
        let f = FakeTransport::new(move |_, cmd| {
            if is_probe(cmd) {
                ok(&converged)
            } else {
                ok("already\n")
            }
        });
        let t = Target::parse("admin@mini-1.local").unwrap();
        let r = up_host(&f, &t, &settings(Some("fvjt_abc.SECRETSECRET")));
        assert!(r.ok, "{:?}", r.error);
        assert_eq!(
            r.steps.iter().map(|s| s.name.as_str()).collect::<Vec<_>>(),
            ["install", "daemon"]
        );
        assert!(
            f.calls_for("mini-1.local")
                .iter()
                .all(|c| c.stdin.is_none())
        );
    }

    #[test]
    fn preflight_errors_stop_before_anything_is_installed() {
        let f = FakeTransport::new(|_, cmd| {
            if is_probe(cmd) {
                ok(&FRESH.replace("arch=arm64", "arch=x86_64"))
            } else {
                ok("")
            }
        });
        let r = up_host(
            &f,
            &Target::parse("m").unwrap(),
            &settings(Some("fvjt_abc.SECRETSECRET")),
        );
        assert!(!r.ok && r.steps.is_empty());
        assert!(r.error.unwrap().contains("Apple silicon"));
        assert_eq!(f.calls.lock().unwrap().len(), 1, "only the probe ran");
    }

    #[test]
    fn a_different_installed_version_points_at_upgrade() {
        let f = FakeTransport::new(|_, cmd| {
            if is_probe(cmd) {
                ok(&FRESH
                    .replace("fluxctl_version=", "fluxctl_version=0.4.20")
                    .replace("agent_binary=no", "agent_binary=yes"))
            } else {
                ok("")
            }
        });
        let r = up_host(
            &f,
            &Target::parse("m").unwrap(),
            &settings(Some("fvjt_abc.SECRETSECRET")),
        );
        assert!(r.error.unwrap().contains("mac-fleet upgrade"));
    }

    #[test]
    fn an_unenrolled_mac_without_a_token_is_refused_not_half_enrolled() {
        let f = healthy_fake();
        let r = up_host(&f, &Target::parse("m").unwrap(), &settings(None));
        assert!(!r.ok && r.error.unwrap().contains("join token"));
        assert!(r.steps.is_empty());
    }

    #[test]
    fn one_unreachable_mac_does_not_stop_the_others() {
        let f = FakeTransport::new(|t, cmd| {
            if t.host == "down.local" {
                failed(
                    255,
                    "ssh: connect to host down.local port 22: Connection refused",
                )
            } else if is_probe(cmd) {
                ok(FRESH)
            } else {
                ok("done\n")
            }
        });
        let targets: Vec<Target> = ["a.local", "down.local", "b.local"]
            .iter()
            .map(|h| Target::parse(h).unwrap())
            .collect();
        let s = settings(Some("fvjt_abc.SECRETSECRET"));
        let rs = par_map(&targets, 3, |t| up_host(&f, t, &s));
        assert_eq!(
            rs.iter().map(|r| r.ok).collect::<Vec<_>>(),
            [true, false, true]
        );
        assert!(rs[1].error.as_ref().unwrap().contains("Remote Login"));
        assert!(
            finish(&rs, "up")
                .unwrap_err()
                .to_string()
                .contains("1 of 3")
        );
        assert!(render_results("UP", &rs).contains("FAILED"));
    }

    #[test]
    fn a_failing_step_stops_that_mac_and_names_the_step() {
        let f = FakeTransport::new(|_, cmd| {
            if is_probe(cmd) {
                ok(FRESH)
            } else if cmd.contains("sha256") && cmd.contains("curl") {
                failed(1, "checksum mismatch: got x, the release says y")
            } else {
                ok("")
            }
        });
        let r = up_host(
            &f,
            &Target::parse("m").unwrap(),
            &settings(Some("fvjt_abc.SECRETSECRET")),
        );
        assert!(!r.ok);
        assert!(
            r.error.as_ref().unwrap().contains("`install`")
                && r.error.unwrap().contains("checksum mismatch")
        );
        assert_eq!(r.steps.len(), 1);
    }

    #[test]
    fn remote_output_never_leaks_a_token() {
        let f = FakeTransport::new(|_, cmd| {
            if is_probe(cmd) {
                ok(FRESH)
            } else {
                failed(1, "bad token fvjt_abc.SECRETSECRET rejected")
            }
        });
        let r = up_host(
            &f,
            &Target::parse("m").unwrap(),
            &settings(Some("fvjt_abc.SECRETSECRET")),
        );
        assert!(!r.ok);
        assert!(!format!("{r:?}").contains("SECRETSECRET"));
        assert!(!render_results("UP", &[r]).contains("SECRETSECRET"));
    }

    #[test]
    fn upgrade_refuses_running_vms_unless_forced() {
        let busy = FRESH
            .replace("fluxctl_version=", "fluxctl_version=0.4.20")
            .replace(
                "vms_json=",
                "vms_json={\"items\":[{\"status\":\"running\",\"request\":{}}]}",
            );
        let f = FakeTransport::new(move |_, cmd| if is_probe(cmd) { ok(&busy) } else { ok("ok") });
        let i = settings(None).install;
        let t = Target::parse("m").unwrap();
        let r = upgrade_host(&f, &t, &i, false);
        assert!(!r.ok && r.error.unwrap().contains("--force"));
        assert!(upgrade_host(&f, &t, &i, true).ok);
    }

    #[test]
    fn status_is_one_row_per_mac_with_slots() {
        let up = FRESH
            .replace("fluxctl_version=", "fluxctl_version=0.4.21")
            .replace("daemon_loaded=no", "daemon_loaded=yes")
            .replace("daemon_healthy=no", "daemon_healthy=yes")
            .replace("vms_json=", "vms_json={\"items\":[{\"status\":\"running\",\"request\":{\"apple\":{\"guest_os\":\"macos\"}}}]}")
            .replace("kube_json=", "kube_json={\"vm\":null,\"api_answers\":false}");
        let f = FakeTransport::new(move |t, _| {
            if t.host == "down" {
                failed(255, "Permission denied (publickey).")
            } else {
                ok(&up)
            }
        });
        let rows = vec![
            status_host(&f, &Target::parse("a").unwrap()),
            status_host(&f, &Target::parse("down").unwrap()),
        ];
        let table = render_status(&rows);
        assert!(
            table.contains("ok")
                && table.contains("0.4.21")
                && table.contains("1/2")
                && table.contains("none")
        );
        assert!(table.contains("unreachable") && table.contains("ssh-copy-id"));
    }

    #[test]
    fn exec_reports_each_macs_exit_status() {
        let f = FakeTransport::new(|t, _| {
            if t.host == "bad" {
                ExecOut {
                    code: 3,
                    stdout: String::new(),
                    stderr: "nope\n".into(),
                }
            } else {
                ok("hi\n")
            }
        });
        let (a, out) = exec_host(
            &f,
            &Target::parse("a").unwrap(),
            &["echo".into(), "hi".into()],
        );
        assert!(a.ok && out == "hi\n");
        let (b, out) = exec_host(&f, &Target::parse("bad").unwrap(), &["false".into()]);
        assert!(!b.ok && b.error.unwrap().contains("3") && out == "nope\n");
    }

    #[test]
    fn dry_run_prints_ssh_lines_and_sends_nothing() {
        let d = DryTransport::new(SshOpts::default());
        let mut t = Target::parse("admin@mini-1.local").unwrap();
        t.k3s = true;
        let r = up_host(&d, &t, &settings(Some("fvjt_abc.SECRETSECRET")));
        assert!(r.ok);
        let lines = d.lines.lock().unwrap().clone();
        assert_eq!(
            lines.len(),
            6,
            "probe + install, daemon, join-token, enroll, k3s"
        );
        assert!(
            lines
                .iter()
                .all(|l| l.starts_with("ssh -T -o BatchMode=yes -o StrictHostKeyChecking=yes"))
        );
        assert!(lines.iter().all(|l| !l.contains("SECRETSECRET")));
        assert!(lines[3].contains("# stdin: the join token (21 bytes, not shown)"));
    }

    #[test]
    fn par_map_keeps_order_and_runs_everything() {
        let items: Vec<u32> = (0..50).collect();
        assert_eq!(
            par_map(&items, 8, |i| i * 2),
            items.iter().map(|i| i * 2).collect::<Vec<_>>()
        );
        assert!(par_map::<u32, u32>(&[], 4, |i| *i).is_empty());
    }

    #[test]
    fn settings_pin_the_version_and_refuse_latest_and_a_stray_token() {
        let flags = |v: &str| UpFlags {
            release: Some(v.into()),
            sha256: None,
            release_base: None,
            via: Via::Release,
            central: Some("https://c:1".into()),
            advertise_url: None,
            token_file: None,
            token_stdin: false,
            k3s: false,
            k3s_cpus: None,
            k3s_memory_mib: None,
            k3s_disk_gib: None,
            k3s_wait: None,
            labels: vec![],
        };
        let mut t = vec![Target::parse("a").unwrap()];
        assert!(build_settings(&flags("latest"), None, &mut t, None).is_err());
        assert!(build_settings(&flags("0.4.21"), None, &mut t, None).is_ok());
        let mut f = flags("0.4.21");
        f.central = None;
        f.k3s = true;
        let s = build_settings(&f, None, &mut t, Some("rack-a")).unwrap();
        assert!(t[0].k3s && t[0].name == "rack-a" && s.token.is_none());
        let mut two = vec![Target::parse("a").unwrap(), Target::parse("b").unwrap()];
        assert!(build_settings(&flags("0.4.21"), None, &mut two, Some("x")).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn a_token_file_others_can_read_is_refused() {
        use std::os::unix::fs::PermissionsExt;
        let d = tempfile::tempdir().unwrap();
        let p = d.path().join("t");
        std::fs::write(&p, "fvjt_abc.def\n").unwrap();
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o644)).unwrap();
        assert!(
            read_token(Some(&p), false)
                .unwrap_err()
                .to_string()
                .contains("chmod 600")
        );
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o600)).unwrap();
        let s = read_token(Some(&p), false).unwrap().unwrap();
        assert_eq!(s.expose(), b"fvjt_abc.def");
        assert!(read_token(Some(&p), true).is_err());
    }
}
